def _s(
    pt: str,
    en: str,
    es: str,
    fr: str,
    de: str,
    it: str,
    hi: str,
    ar: str,
    ja: str,
    zh: str,
    ru: str,
    ko: str,
) -> dict[str, str]:
    return {
        "pt": pt,
        "en": en,
        "es": es,
        "fr": fr,
        "de": de,
        "it": it,
        "hi": hi,
        "ar": ar,
        "ja": ja,
        "zh": zh,
        "ru": ru,
        "ko": ko,
    }


def _brand(name: str) -> dict[str, str]:
    return _s(name, name, name, name, name, name, name, name, name, name, name, name)


